class Solution:
    def evalRPN(self, tokens: list[str]) -> int:
        arr = tokens[:]
        ops = {"+", "-", "*", "/"}
        while len(arr) > 1:
            for i, tok in enumerate(arr):
                if tok in ops:
                    a, b = int(arr[i - 2]), int(arr[i - 1])
                    if tok == "+":
                        val = a + b
                    elif tok == "-":
                        val = a - b
                    elif tok == "*":
                        val = a * b
                    else:
                        val = int(a / b)  # Truncates toward zero.
                    arr[i - 2:i + 1] = [str(val)]
                    break
        return int(arr[0])

solutions.better:
class Solution:
    def evalRPN(self, tokens: list[str]) -> int:
        stack = []
        for tok in tokens:
            if tok not in "+-*/":
                stack.append(int(tok))
                continue
            b = stack.pop()
            a = stack.pop()
            # Apply the operator to the earlier operand first.
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                stack.append(int(a / b))
        return stack[-1]

solutions.optimal:
class Solution:
    def evalRPN(self, tokens: list[str]) -> int:
        def div(a: int, b: int) -> int:
            return int(a / b)  # LeetCode requires truncation toward zero.

        ops = {
            "+": lambda a, b: a + b,
            "-": lambda a, b: a - b,
            "*": lambda a, b: a * b,
            "/": div,
        }
        stack = []
        for tok in tokens:
            if tok in ops:
                b = stack.pop()
                a = stack.pop()
                stack.append(ops[tok](a, b))
            else:
                stack.append(int(tok))
        return stack.pop()

